public class InnerProcessingJobDatasetDefinitionFactory(Action<Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition> factoryAction = null) : SubResourceFactory<Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition>
{

    internal InnerProcessingJobRedshiftDatasetDefinitionFactory RedshiftDatasetDefinitionFactory { get; set; }

    internal InnerProcessingJobAthenaDatasetDefinitionFactory AthenaDatasetDefinitionFactory { get; set; }

    protected override Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition Create()
    {
        var datasetDefinitionResult = CreateDatasetDefinition();
        factoryAction?.Invoke(datasetDefinitionResult);

        return datasetDefinitionResult;
    }

    private Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition CreateDatasetDefinition()
    {
        var datasetDefinitionResult = new Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition();

        return datasetDefinitionResult;
    }
    public override void CreateChildren(Humidifier.SageMaker.ProcessingJobTypes.DatasetDefinition result)
    {
        base.CreateChildren(result);

        result.RedshiftDatasetDefinition ??= RedshiftDatasetDefinitionFactory?.Build();
        result.AthenaDatasetDefinition ??= AthenaDatasetDefinitionFactory?.Build();
    }

} // End Of Class

